cd /tmp && /usr/bin/python3 -I - <<'EOF'
import csv, json
from datetime import date
from decimal import Decimal
from pathlib import Path
R=Path('/app/inputs')
pol=json.loads((R/'policy.json').read_text())
rows=list(csv.DictReader((R/'statement.csv').open()))
rec=[]
for p in sorted((R/'receipts').glob('*.txt')):
    d={}
    for l in p.read_text().splitlines():
        k,s,v=l.partition(':')
        if s and k.strip() in {'RECEIPT-ID','DATE','TOTAL'}: d[k.strip()]=v.strip()
    rec.append((d['RECEIPT-ID'],date.fromisoformat(d['DATE']),int(Decimal(d['TOTAL'])*100)))
for t in rows:
    a=abs(int(t['amount_cents'])); dt=date.fromisoformat(t['posted_date'])
    for rid,rd,c in rec:
        ad=abs(c-a); dd=abs((rd-dt).days)
        if ad<=pol['amount_tolerance_cents'] or (ad<=60):
            print(t['txn_id'],rid,'amt',ad,'days',dd,'ELIGIBLE' if ad<=50 and dd<=3 else 'no')
EOF
